{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Asciminib, which shares the 3-hydroxyazetidine and heteroaromatic polar framework with the query, has an absolute oral bioavailability of approximately 73% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Lemborexant, a heteroaromatic oral drug with fluorophenyl and amide/ether motifs, has at least 87% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Paliperidone has 28% absolute oral bioavailability in healthy fasting volunteers, which is above the 20% threshold and supports high F despite moderate absorption limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Lumateperone has an absolute oral bioavailability of about 4.4% in humans, a contradictory low-F example, but its fused tricyclic piperazine scaffold and extensive first-pass metabolism are not shared by the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because the most transferable human oral bioavailability evidence, including azetidinol/heteroaromatic analogues such as asciminib (~73%) and lemborexant (>=87%), supports F above 20%; the only low-F analogue (lumateperone, ~4.4%) is structurally distant and its metabolic liability is unlikely to transfer.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule; all evidence is from analogues with low Morgan similarity (~0.21-0.23).",
    "The low-F lumateperone example is structurally distant and its first-pass metabolism liability may not be representative.",
    "Some supportive records are predicted or formulation-dependent (e.g., paliperidone ER), adding uncertainty to exact F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

